// This is start of the header guard. By convention, we use the name of the header file.
#ifndef MAKE_SURFACE_MESH_H
#define CGAL_SEARCH_WITH_POINT_H
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Polyhedron_3.h>
#include <CGAL/IO/Polyhedron_iostream.h>
#include <CGAL/boost/graph/graph_traits_Polyhedron_3.h>
#include <CGAL/point_generators_3.h>
#include <CGAL/Side_of_triangle_mesh.h>
#include <CGAL/Surface_mesh.h>
#include <vector>
#include <fstream>
#include <limits>
#include <boost/foreach.hpp>

typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef K::Point_3 Point3d;
typedef CGAL::Surface_mesh<Point3d> Surface_mesh;
typedef CGAL::Polyhedron_3<K> Polyhedron;

class cgal_surface_mesh{
public:
	cgal_surface_mesh();
	~cgal_surface_mesh();

	// Polyhedron
	Polyhedron polyHedron();

	// Make surface mesh based on the input off format file and output
	// the triangulated surface mesh
	int makeSurfaceMesh(const std::string strfile, Surface_mesh &surfacemesh);

	// Make surface mesh based on the input off format file and output the
	// triangulated surface mesh to off format file
	int makeSurfaceMeshToOff(const std::string strfile,const std::string strfileout);

	// Make polyhedron based on the triangulated surface mesh
	int makePolyhedron(const std::string strfile);

	// Determine if a point is inside, on boundary or outside the polyhedron
	int isInsidePolyhedron(const Point3d pt);

protected:

private:
	Polyhedron polyhedron;

};

// This is the end of the header guard
#endif

